mapper.select:
SELECT sl.*, u.user_name AS userName, c.NAME AS customerName FROM t_sale_list sl LEFT JOIN t_user u ON sl.user_id = u.id LEFT JOIN t_customer c ON sl.customer_id = c.id
sl.sale_number =#{saleListQuery.saleNumber}
and sl.customer_id=#{saleListQuery.customerId}
and sl.state = #{saleListQuery.state}
and sale_date >= TO_DATE(#{saleListQuery.startDate}, 'YYYY-MM-DD')
and sale_date <= TO_DATE(#{saleListQuery.endDate}, 'YYYY-MM-DD')
